defaults={21:'Bien',27:'passage',29:r'n\textsuperscript{o} 4',32:r'n\textsuperscript{o}4',34:r'n\textsuperscript{o}s'}
for i,c in enumerate(changes):
 a,b=mapping[i]
 c['readers']={'r1':' ; '.join(R('r1',j) for j in a) if a else defaults.get(i,'same visible text, no separate discrepancy reported'), 'r2':c['reading'], 'r3':' ; '.join(R('r3',j) for j in b) if b else defaults.get(i,'same visible text, no separate discrepancy reported')}
