top=r'\unsure{1.9.3|1.93|1.9.5}, \unsure{1.27|1.23}, 2.9 à reporter au \unsure{n\textsuperscript{o} 3}\unsure{?}\\3.1'
changes[0].update(reading=top,evidence='Main crop 01: terminal pale digit in the first reference and its second separator remain weak; second reference ends in a 7/3-like faded turn. The separate lower 3.1 has a clear 3, dot and upright 1, so that part is resolved. The very pale destination and query belong to the upper line; no query is securely visible after the lower 3.1. No top-note dash is visible between 2.9 and à.')
changes[2].update(reading=r'\uline{\unsure{pp|pv|pr}}',confidence='low',evidence='Main crop 03: the first glyph has a p stem and shoulder. The second has two upward strokes joined low and an open right end; pp, pv and pr remain possible. The continuous underline is definite. H describes it as illegible rather than supplying letters.')
appendix=r'\deleted{Existence de point\unsure{s}} \unsure{\deleted{d\x27}Un|\deleted{d\x27Un}}'.replace(r'\x27',"'")
changes[18].update(reading=appendix,confidence='medium',evidence='Main crop 14: Existence de point is readable beneath the strike, with the terminal s less separable. The crossed short d/apostrophe-like run and larger Un are visible, but the strike boundary does not securely settle whether Un remains live. This narrows C’s whole-phrase doubt while retaining the local final-letter and state uncertainties; it is not a grammatical reconstruction.')
changes[19].update(reading=r'\unsure{a} \inserted{suffisamment de points}\unsure{.}',evidence='Main crop 14: sufficiently separated paired f strokes, low joins and terminal t support suffisamment; de points follows directly, without an extra word. The small a-like form and faint final punctuation remain uncertain. R1’s full-word suffisamment doubt is narrowed, but r1’s definite a and r2’s definite final period are not adopted.')
changes[22].update(reading=r'\deleted{\unsure{9|8}}\handwritten{8}',confidence='low',evidence='Main crop 16: a large freehand 8 surrounds smaller regular curved remnants. The upper bowl does not distinguish a typed 9 from 8; both underprint candidates remain. R3’s hand-state-only reading loses those smaller remnants, while r2’s single 9 candidate is too narrow. H acknowledges overwritten 8s in a note.')
changes[26]['evidence']='Main crop 18: u stems coexist with a descending curved stroke and obscured rounded body. The upper closure cannot distinguish g from y; both and both correction orders remain. R1 gives g, r3 gives y; main retains the ink-supported alternatives.'
changes[27].update(reading=R('r3',31),confidence='medium',evidence='Main crop 18: a tall serifed ascender and a p descender coexist in the first cell. The shared right bowl does not distinguish a b component from an l component over p. Both b/p and l/p, in either order, remain; plain passage omits the extra ascender.')
changes[28].update(reading=r'\deleted{\unsure{9}}\handwritten{8}',confidence='medium',evidence='Main crop 19: inside the large handwritten 8, a smaller upper bowl and lower hook favor typed 9. Their partly merged outlines warrant a local doubt; no independent second typed bowl establishes 8. H acknowledges the overwritten figures in its note.')
changes[30].update(reading=r'\deleted{à la rigue}',confidence='medium',evidence='Main crop 20: under the x cancellation there are visible slots for à, la, r-i-g-u-e. The last cell has a curved e body and middle bar. No following u/r slots are visible. R1’s shorter literal run is adopted; r2’s completed rigueur and r3’s final r candidate are rejected from spacing and the terminal body, not from idiom.')
changes[31].update(reading=r't\deleted{\unsure{l|i}}\handwritten{o}mber',confidence='low',evidence='Main crop 21: red oval o is distinct from black vertical/serif remnants. A tall l-like upper serif is favored, but its junction is obscured enough to retain the i alternative; the lower fragment alone does not settle it. Correction layers are retained without pretending the black letter is untouched o.')
changes[35].update(reading=r'ào\unsure{\deleted{p}m|\deleted{m}p}plète',crop='readers/scan018/r1/crops/22_aomplete.jpg',evidence='Main r1 crop 22: a separate grave and closed a body with right stem establish initial à. The word’s third cell has a separate m/p superposition, recorded in its own locus. The initial is not normalized to c.')
changes[36]['evidence']='Main crop 22: the tall continuous closing parenthesis is handwritten; the following separate slanted black mark does not securely distinguish comma and full stop. R3’s definite comma is not adopted. The parenthesis insertion state agrees with H; only punctuation certainty differs from H.'
changes[37]['evidence']='Main crop 23: d’objet is legible, followed by a very faint terminal turn; it could be s, but the separated contours needed to resolve it are absent. R3’s definite singular is too strong, as is H’s definite plural. C’s local s doubt remains.'
for i in [1,16,21,25,26,27]:changes[i]['evidence']+=' H explicitly says typewriter superpositions are not recorded; this is a difference in declared transcription scope, not a concealed H uncertainty.'
