def add(locus,c,h,reading,dc,dh,kind,confidence,evidence,crop,readers):
 changes.append(dict(locus=locus,c=c,h=h,reading=reading,diff_c=dc,diff_h=dh,kind=kind,marked_in_H=False,confidence=confidence,evidence=evidence,crop=crop,readers=readers,mathematical_consequence=''))
add('Sommaire underline state',r'\uline{Sommaire}',r'\emph{Sommaire}',r'\uline{Sommaire}',False,True,'other','high','Main title crop shows a continuous underline beneath ordinary upright typed Sommaire. H uses emph; its supplied style loads ulem with normalem, so emph remains italic rather than underlined. The common emphasis function does not preserve this visible source state. All readers transcribe the underline; r3’s equivalence policy is rejected.',mainpath('title'),{r:r'\uline{Sommaire}' for r in rs})
add('Top note after 2.9: absent dash','2.9 à','2.9 --- à','2.9 à',False,True,'text not on the page','medium','Main top-note crop shows a blank interval between 2.9 and à with no secure dash. This is presence/absence of a source mark, not the v006 distinction between hyphen and en-dash encodings of the same mark.',changes[0]['crop'],{'r1':R('r1',3),'r2':'2.9 à','r3':'2.9 -- à'})
add('Last paragraph third cell of àomplète','àomplète/complète (no overprint state)','complète',r'ào\unsure{\deleted{p}m|\deleted{m}p}plète',True,True,'misread word','high','Main r1 crop 22 shows the m shoulders together with a separate descending p stem and foot in the third cell. Both letters are secure; their order is not. R2 omits this layer. H expressly omits typewriter superpositions.','readers/scan018/r1/crops/22_aomplete.jpg',{'r1':R('r1',32),'r2':'àomplète','r3':R('r3',38)})
add('NB second sûr: last cell superposition','sûr','sûr',R('r3',32),True,True,'misread word','high','Main sûr crop shows a full t ascender/crossbar/curved foot together with an r shoulder and baseline foot. Both letters occupy one cell; order remains unknown. R1/r2 leave this unnoticed. H expressly omits typewriter superpositions.',mainpath('sur'),{'r1':'sûr','r2':'sûr','r3':R('r3',32)})
bottom=R('r1',36)
add('Bottom handwritten insertion cancellation scope','live insertion','live insertion',bottom,True,True,'deletion state (struck given live or live given struck)','low','Main crop 23 shows a long diagonal crossing the addition. R2 keeps it live, r3 treats it as cancelled, r1 marks state uncertainty. The crossing is definite, but the image does not establish whether this insertion was intended to remain under an older cancellation grid. The outer unsure marks this live/cancelled-state doubt; no chronology is assigned.',changes[37]['crop'],{r:R(r,i) for r,i in [('r1',36),('r2',37),('r3',42)]})
changes[-1]['readers']['r2']='live insertion; final s uncertain'
adjudications=[dict(locus='38 à 46: alleged 2 under 3',readers={'r1':'38 à 46','r2':'38 à 46','r3':R('r3',8)},reading='38 à 46',crop=mainpath('ranges'),evidence='Main range crop shows the joined upper and lower turns of a retraced 3. The middle horizontal/diagonal can belong to that one glyph; there is no separately established complete 2 with its own lower foot. No deleted 2 is asserted. Final equals both witnesses; no collation row.')]
